            var buffer = new Span<byte>(target + 65 * i, 65);
            buffer.Clear();
            // Encoder.Convert never cuts a UTF-8 sequence in the middle.
            Encoding.UTF8.GetEncoder().Convert(fields[i].AsSpan(), buffer[..64], true, out _, out _, out _);
        }
        return 0;
    }
}


